<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/db.php'; $adminUser=requireAdmin(); $adminPageTitle='Reports';
$rows=$adminConnection->query('SELECT center_name, COUNT(*) AS total FROM appointments GROUP BY center_name ORDER BY total DESC')->fetchAll(); $monthly=$adminConnection->query("SELECT DATE_FORMAT(appointment_date,'%Y-%m') AS month, COUNT(*) AS total FROM appointments GROUP BY month ORDER BY month DESC LIMIT 12")->fetchAll(); require __DIR__ . '/includes/header.php';
